SELECT VARIANCE("L_DIVERSIONS"."Code"), MIN("L_DIVERSIONS"."Code"), MAX("L_STATE_FIPS"."Code"), MAX("L_STATE_FIPS"."Code"), "L_DIVERSIONS"."Code" FROM "L_STATE_FIPS" CROSS JOIN "L_AIRPORT" CROSS JOIN "L_DIVERSIONS" CROSS JOIN "L_WEEKDAYS" WHERE "L_STATE_FIPS"."Code" >= 51 AND "L_STATE_FIPS"."Code" IS NOT NULL AND "L_DIVERSIONS"."Code" > 6 GROUP BY "L_STATE_FIPS"."Description", "L_DIVERSIONS"."Code" LIMIT 1000;
SELECT MIN("On_Time_On_Time_Performance_2016_1"."Div1TotalGTime"), "On_Time_On_Time_Performance_2016_1"."OriginAirportSeqID", "L_AIRPORT_ID"."Code" FROM "On_Time_On_Time_Performance_2016_1" LEFT JOIN "L_AIRPORT_ID" ON "On_Time_On_Time_Performance_2016_1"."DestAirportID" = "L_AIRPORT_ID"."Code" WHERE "L_AIRPORT_ID"."Code" >= 37639 AND "On_Time_On_Time_Performance_2016_1"."CRSArrTime" = 29 AND "L_AIRPORT_ID"."Code" <= 10875 GROUP BY "On_Time_On_Time_Performance_2016_1"."Div2AirportID", "On_Time_On_Time_Performance_2016_1"."DepTimeBlk";
SELECT AVG("L_AIRPORT_ID"."Code") FROM "L_AIRPORT_ID" WHERE "L_AIRPORT_ID"."Description" LIKE '%u%' AND "L_AIRPORT_ID"."Description" IS NULL AND "L_AIRPORT_ID"."Description" LIKE '%u%' AND "L_AIRPORT_ID"."Description" LIKE '%a%' AND "L_AIRPORT_ID"."Description" = 'Curuzu Cuatia, Argentina: Curuzu Cuatia Airport' AND "L_AIRPORT_ID"."Description" IS NULL AND "L_AIRPORT_ID"."Code" < 11885 GROUP BY "L_AIRPORT_ID"."Description";
SELECT MAX("On_Time_On_Time_Performance_2016_1"."Div2AirportID"), STDDEV("On_Time_On_Time_Performance_2016_1"."OriginAirportSeqID"), MAX("On_Time_On_Time_Performance_2016_1"."Quarter") FROM "On_Time_On_Time_Performance_2016_1" JOIN "L_YESNO_RESP" ON "On_Time_On_Time_Performance_2016_1"."ArrDel15" = "L_YESNO_RESP"."Code" WHERE "L_YESNO_RESP"."Code" != 0 AND "L_YESNO_RESP"."Code" != 0 AND "On_Time_On_Time_Performance_2016_1"."Carrier" = 'EV';
SELECT MIN("L_MONTHS"."Code"), COUNT(*), COUNT(*), COUNT(*), "L_MONTHS"."Code", "L_AIRPORT_SEQ_ID"."Description" FROM "L_MONTHS" CROSS JOIN "L_AIRPORT_SEQ_ID" WHERE "L_MONTHS"."Description" = 'January' GROUP BY "L_MONTHS"."Description" HAVING AVG(1) < 12;
SELECT VARIANCE("L_QUARTERS"."Code"), STDDEV("L_DIVERSIONS"."Code"), SUM("L_DIVERSIONS"."Code"), AVG("L_AIRLINE_ID"."Code") FROM "L_DIVERSIONS" CROSS JOIN "L_QUARTERS" CROSS JOIN "L_WORLD_AREA_CODES" CROSS JOIN "L_AIRLINE_ID" CROSS JOIN "L_STATE_FIPS" WHERE "L_STATE_FIPS"."Code" > 20 AND "L_WORLD_AREA_CODES"."Code" <= 438 AND "L_WORLD_AREA_CODES"."Code" IS NOT NULL AND "L_QUARTERS"."Code" = 1 GROUP BY "L_WORLD_AREA_CODES"."Code", "L_STATE_FIPS"."Code" HAVING AVG(1) >= 50 ORDER BY "L_WORLD_AREA_CODES"."Code", "L_STATE_FIPS"."Code" ASC;
SELECT STDDEV("L_AIRLINE_ID"."Code"), VARIANCE("L_DIVERSIONS"."Code"), "L_DIVERSIONS"."Description" FROM "L_AIRPORT_ID" CROSS JOIN "L_WEEKDAYS" CROSS JOIN "L_DIVERSIONS" CROSS JOIN "L_AIRPORT" CROSS JOIN "L_AIRLINE_ID" WHERE "L_AIRPORT"."Code" != 'A75' GROUP BY "L_DIVERSIONS"."Code", "L_DIVERSIONS"."Description" ORDER BY "L_DIVERSIONS"."Code", "L_DIVERSIONS"."Description" ASC;
SELECT COUNT(*) FROM "L_CANCELLATION" CROSS JOIN "L_STATE_ABR_AVIATION" CROSS JOIN "L_AIRPORT" WHERE "L_AIRPORT"."Code" LIKE '%e%' AND "L_AIRPORT"."Code" IS NOT NULL AND "L_STATE_ABR_AVIATION"."Code" != 'NL' GROUP BY "L_CANCELLATION"."Code", "L_CANCELLATION"."Code" HAVING COUNT(*) = 16;
SELECT SUM("L_QUARTERS"."Code"), COUNT(*), "L_QUARTERS"."Description", "L_QUARTERS"."Description", "L_STATE_ABR_AVIATION"."Description" FROM "L_QUARTERS" CROSS JOIN "L_STATE_ABR_AVIATION" WHERE "L_STATE_ABR_AVIATION"."Code" LIKE '%o%' OR "L_STATE_ABR_AVIATION"."Code" IS NULL AND "L_QUARTERS"."Description" LIKE '%o%' AND "L_STATE_ABR_AVIATION"."Code" LIKE '%a%';
SELECT AVG("L_CITY_MARKET_ID"."Code"), "L_QUARTERS"."Description", "L_QUARTERS"."Description", "L_DIVERSIONS"."Description" FROM "L_QUARTERS" CROSS JOIN "L_DIVERSIONS" CROSS JOIN "L_CANCELLATION" CROSS JOIN "L_CITY_MARKET_ID" WHERE "L_CITY_MARKET_ID"."Code" != 31671 AND "L_CITY_MARKET_ID"."Code" IS NULL AND "L_CITY_MARKET_ID"."Code" < 32711 AND "L_CITY_MARKET_ID"."Code" < 32247 AND "L_QUARTERS"."Code" >= 1 OR "L_QUARTERS"."Code" IS NOT NULL AND "L_CITY_MARKET_ID"."Code" = 32294 GROUP BY "L_QUARTERS"."Code" LIMIT 10;
